	const wrapper = frm.fields_dict[fieldname]?.$wrapper?.get(0);
	if (!wrapper) return;

	const apply = () => {
		wrapper.querySelectorAll('.unit-checkbox input[type="checkbox"][data-unit]').forEach((input) => {
			if (!BP_HIDDEN_ROLES.includes(input.dataset.unit)) return;
			const unit = input.closest(".unit-checkbox");
			if (unit && unit.style.display !== "none") unit.style.display = "none";
			// Only write when it changes, so the observer below does not loop.
			if (!input.disabled) input.disabled = true;
		});
	};

	apply();
	// The checkboxes render async (roles come from a server call), and the core editor re-enables
	// them in set_enable_disable, so keep re-applying whenever the editor changes.
	if (!wrapper.bp_role_whitelist_observer) {
		wrapper.bp_role_whitelist_observer = new MutationObserver(apply);
		wrapper.bp_role_whitelist_observer.observe(wrapper, {
			childList: true,
			subtree: true,
			attributes: true,
			attributeFilter: ["disabled"],
		});
	}
}

frappe.ui.form.on("User", {
	refresh(frm) {
		bp_apply_role_whitelist(frm, "roles_html");
	},
});

